require("binds")
local mainMod = "SUPER"

hl.bind(mainMod .. " + SUPER_L", hl.dsp.exec_cmd("~/.config/hypr/utilities/session/shells.sh launcher"), { release = true, description = "Shell · Launcher" })
hl.bind(mainMod .. " + SHIFT + P", hl.dsp.exec_cmd("~/.config/hypr/utilities/session/shells.sh profiles"), { description = "Shell · Profiles" })
hl.bind(mainMod .. " + SHIFT + L", hl.dsp.exec_cmd("~/.config/hypr/utilities/session/lock.sh"), { description = "Shell · Lock" })
hl.bind("ALT + TAB", hl.dsp.exec_cmd("~/.config/hypr/utilities/session/shells.sh home"), { description = "Shell · Home" })
hl.bind("ALT + w", hl.dsp.exec_cmd("~/.config/hypr/utilities/session/shells.sh wallpaper"), { description = "Shell · Wallpaper" })
hl.bind("ALT + a", hl.dsp.exec_cmd("~/.config/hypr/utilities/bars/bar.sh toggle"), { description = "Shell · Toggle bar" })
hl.bind(mainMod .. " + grave", hl.dsp.exec_cmd("~/.config/hypr/utilities/session/shells.sh overview"), { description = "Shell · Overview" })
hl.bind("ALT + S", hl.dsp.exec_cmd("~/.config/hypr/utilities/session/shells.sh settings"), { description = "Shell · Settings" })
hl.bind("ALT + RETURN", hl.dsp.exec_cmd("~/.config/hypr/utilities/session/shells.sh music"), { description = "Shell · Music player" })
hl.bind(mainMod .. " + SHIFT + ESCAPE", hl.dsp.exit(), { description = "Shell · Log out" })
hl.bind(mainMod .. " + ESCAPE", hl.dsp.exec_cmd("~/.config/hypr/quickshell/shared/spotify.sh toggle"), { description = "Media · Spotify" })
hl.bind(mainMod .. " + SHIFT + slash", hl.dsp.exec_cmd("~/.config/hypr/utilities/session/shells.sh keybinds toggle"), { description = "Shell · Keybind sidebar" })
hl.bind("ALT + SHIFT + slash", hl.dsp.exec_cmd("~/.config/hypr/utilities/session/shells.sh keybinds extend"), { description = "Shell · Keybind sidebar (all)" })
